-- Research library, part 2 (coaching platform program, chunk E2) -------------------------

-- Loads the first sources into the library tables from E1 and fills their embeddings on the
-- server, with no manual step in production:
--
--  1. private.library_replace_source loads (or re-loads) one source with its chunks. The
--     blocks at the end of this file call it. A later content update is a new migration with
--     the blocks for the changed sources (supabase/functions/_shared/library/migration_sql.ts).
--     Chunks load without an embedding; full-text search finds them at once.
--  2. The library-embed Edge Function fills the missing embeddings with Supabase's built-in
--     gte-small model (decision D4). A pg_cron job calls it every minute while any chunk
--     lacks an embedding, authenticating with a secret the database generates in Vault.
--     Nothing is configured by hand: the secret never leaves the database and the function.
--
-- Everything here is service-role only. Rules still decide every number; the library only
-- grounds wording.

create extension if not exists pg_net with schema extensions;

-- Loading ----------------------------------------------------------------------------------

-- Upserts a source by manifest_key and makes its chunks match chunk_data. Chunks are replaced
-- only when their text differs from what is stored, so loading the same block again keeps
-- the embeddings. Run by migrations as the table owner; nothing else may call it.
create function private.library_replace_source(source_data jsonb, chunk_data jsonb)
returns uuid
language plpgsql
set search_path = ''
as $$
declare
  sid uuid;
begin
  insert into private.library_sources (
    manifest_key, title, authors, year, doi, url, licence, region, topics, evidence_level, kind
  )
  values (
    source_data ->> 'slug',
    source_data ->> 'title',
    array(select jsonb_array_elements_text(source_data -> 'authors')),
    (source_data ->> 'year')::smallint,
    source_data ->> 'doi',
    source_data ->> 'url',
    source_data ->> 'licence',
    array(select jsonb_array_elements_text(source_data -> 'region')),
    array(select jsonb_array_elements_text(source_data -> 'topics')),
    source_data ->> 'evidence_level',
    source_data ->> 'kind'
  )
  on conflict (manifest_key) do update set
    title = excluded.title,
    authors = excluded.authors,
    year = excluded.year,
    doi = excluded.doi,
    url = excluded.url,
    licence = excluded.licence,
    region = excluded.region,
    topics = excluded.topics,
    evidence_level = excluded.evidence_level,
    kind = excluded.kind
  returning id into sid;

  if (
    select coalesce(jsonb_agg(jsonb_build_object(
      'ordinal', c.ordinal, 'section', c.section, 'header', c.header, 'body', c.body
    ) order by c.ordinal), '[]'::jsonb)
    from private.library_chunks c where c.source_id = sid
  ) is distinct from (
    select coalesce(jsonb_agg(jsonb_build_object(
      'ordinal', (e ->> 'ordinal')::integer, 'section', e ->> 'section',
      'header', e ->> 'header', 'body', e ->> 'body'
    ) order by (e ->> 'ordinal')::integer), '[]'::jsonb)
    from jsonb_array_elements(chunk_data) e
  ) then
    delete from private.library_chunks c where c.source_id = sid;
    insert into private.library_chunks (source_id, ordinal, section, header, body, token_count)
    select
      sid,
      (e ->> 'ordinal')::integer,
      e ->> 'section',
      e ->> 'header',
      e ->> 'body',
      (e ->> 'token_count')::integer
    from jsonb_array_elements(chunk_data) e;
  end if;

  return sid;
end
$$;
revoke all on function private.library_replace_source(jsonb, jsonb)
  from public, anon, authenticated, service_role;

-- Worker secret ----------------------------------------------------------------------------

-- The bearer secret for library-embed. It is created in Vault the first time anything asks,
-- so a fresh database (or a restore, which does not carry Vault) heals itself.
create function private.library_worker_secret()
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  secret text;
begin
  select s.decrypted_secret into secret
  from vault.decrypted_secrets s where s.name = 'library_worker_secret';
  if secret is null then
    perform vault.create_secret(
      replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''),
      'library_worker_secret',
      'Bearer secret for the library-embed Edge Function'
    );
    select s.decrypted_secret into secret
    from vault.decrypted_secrets s where s.name = 'library_worker_secret';
  end if;
  return secret;
end
$$;
revoke all on function private.library_worker_secret() from public, anon, authenticated, service_role;

-- True when candidate is the worker secret. The Edge Function calls this with the bearer
-- token it received; a database without the secret yet answers false.
create function public.library_worker_authorized_v1(candidate text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    candidate is not null and candidate <> '' and candidate = (
      select s.decrypted_secret from vault.decrypted_secrets s where s.name = 'library_worker_secret'
    ),
    false
  )
$$;

-- Embedding -------------------------------------------------------------------------------

-- Chunks that still have no embedding, in a stable order. input_text is what both the
-- embedder and full-text search see: the context header, then the body.
create function public.library_pending_chunks_v1(batch_size integer)
returns table (chunk_id uuid, source_id uuid, input_text text)
language sql
stable
security definer
set search_path = ''
as $$
  select
    c.id,
    c.source_id,
    case when c.header = '' then c.body else c.header || E'\n' || c.body end
  from private.library_chunks c
  where c.embedding is null
  order by c.created_at, c.source_id, c.ordinal
  limit least(greatest(coalesce(batch_size, 25), 1), 200)
$$;

-- Stores embeddings from [{chunk_id, embedding: [384 numbers]}] on chunks that have none, and
-- returns how many it stored. Chunks that already have one are left alone, so running the
-- worker twice (or two workers at once) is harmless. A vector of the wrong size raises 22000.
create function public.library_store_embeddings_v1(model text, items jsonb)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  stored integer;
begin
  if model is null or btrim(model) = '' or length(model) > 100 then
    raise exception 'model must be a short non-empty name' using errcode = '22023';
  end if;
  if items is null or jsonb_typeof(items) <> 'array' then
    raise exception 'items must be an array' using errcode = '22023';
  end if;
  if jsonb_array_length(items) > 200 then
    raise exception 'at most 200 items per call' using errcode = '22023';
  end if;

  -- Check every vector first: the update below would not look at those of unknown chunks.
  perform (e -> 'embedding')::text::extensions.vector(384) from jsonb_array_elements(items) e;

  with incoming as (
    select
      (e ->> 'chunk_id')::uuid as id,
      (e -> 'embedding')::text::extensions.vector(384) as embedding
    from jsonb_array_elements(items) e
  )
  update private.library_chunks c
  set embedding = incoming.embedding, embedding_model = model
  from incoming
  where c.id = incoming.id and c.embedding is null;
  get diagnostics stored = row_count;
  return stored;
end
$$;

-- One finished row per worker run that did any work.
create function public.library_record_run_v1(
  started_at timestamptz,
  succeeded boolean,
  source_count integer,
  chunk_count integer,
  error text
)
returns uuid
language sql
security definer
set search_path = ''
as $$
  insert into private.library_ingest_runs (
    started_at, finished_at, status, source_count, chunk_count, error
  )
  values (
    least(started_at, now()),
    now(),
    case when succeeded then 'succeeded' else 'failed' end,
    greatest(coalesce(source_count, 0), 0),
    greatest(coalesce(chunk_count, 0), 0),
    left(error, 2000)
  )
  returning id
$$;

-- Counts for checks and for the retrieval evaluation.
create function public.library_status_v1()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'schema_version', 1,
    'sources', (select count(*) from private.library_sources),
    'chunks', (select count(*) from private.library_chunks),
    'embedded_chunks', (select count(*) from private.library_chunks where embedding is not null)
  )
$$;

revoke all on function public.library_worker_authorized_v1(text) from public, anon, authenticated;
revoke all on function public.library_pending_chunks_v1(integer) from public, anon, authenticated;
revoke all on function public.library_store_embeddings_v1(text, jsonb) from public, anon, authenticated;
revoke all on function public.library_record_run_v1(timestamptz, boolean, integer, integer, text)
  from public, anon, authenticated;
revoke all on function public.library_status_v1() from public, anon, authenticated;
grant execute on function public.library_worker_authorized_v1(text) to service_role;
grant execute on function public.library_pending_chunks_v1(integer) to service_role;
grant execute on function public.library_store_embeddings_v1(text, jsonb) to service_role;
grant execute on function public.library_record_run_v1(timestamptz, boolean, integer, integer, text)
  to service_role;
grant execute on function public.library_status_v1() to service_role;

-- Trigger ---------------------------------------------------------------------------------

-- Calls library-embed when any chunk lacks an embedding; does nothing otherwise. One request
-- embeds only what fits in an Edge Function's CPU limit (about a dozen chunks), so cron calls
-- it every minute until none are left. pg_net sends the request in the background. If the
-- function is not deployed yet (migrations run before the function deploy) the call fails and
-- the next run tries again.
--
-- The target URL is not in this file. It lives in the Vault secret library_embed_url, which only
-- the deploy workflow sets (private.library_set_embed_url). A database without that secret (a
-- local or CI database, or a restore) sends nothing anywhere.

-- Stores the project's library-embed URL in Vault, creating or updating the secret. Refuses
-- anything but https://<20 lowercase letters>.supabase.co/functions/v1/library-embed.
create function private.library_set_embed_url(url text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  secret_id uuid;
begin
  if url is null or url !~ '^https://[a-z]{20}\.supabase\.co/functions/v1/library-embed$' then
    raise exception 'url must be https://<project ref>.supabase.co/functions/v1/library-embed'
      using errcode = '22023';
  end if;
  select s.id into secret_id from vault.secrets s where s.name = 'library_embed_url';
  if secret_id is null then
    perform vault.create_secret(url, 'library_embed_url', 'Target URL of the library-embed Edge Function');
  else
    perform vault.update_secret(secret_id, url);
  end if;
end
$$;
revoke all on function private.library_set_embed_url(text) from public, anon, authenticated;
grant execute on function private.library_set_embed_url(text) to service_role;

create function private.library_embed_kick()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  target_url text;
begin
  select s.decrypted_secret into target_url
  from vault.decrypted_secrets s where s.name = 'library_embed_url';
  if target_url is null or btrim(target_url) = '' then
    return;
  end if;
  if not exists (select 1 from private.library_chunks c where c.embedding is null) then
    return;
  end if;
  perform net.http_post(
    url := target_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || private.library_worker_secret()
    ),
    body := '{}'::jsonb,
    timeout_milliseconds := 60000
  );
end
$$;
revoke all on function private.library_embed_kick() from public, anon, authenticated, service_role;

select cron.schedule(
  'tracend-library-embed',
  '* * * * *',
  'select private.library_embed_kick()'
);

